// CSD_RATIONALE_BEGIN
// The best attempt (41, 49.7% accuracy) uses GroupBoostedConstrainedStep(6.0) with
// IsCompletePrefix early-close. The primary failure mode is 132 syntax_valid_wrong
// answers: the SQL grammar accepts short prefixes like "SELECT city" (2–3 tokens) as
// complete, causing CloseConstrainedSpan to fire far too early before the model has
// generated FROM clauses, WHERE conditions, or GROUP BY/HAVING qualifiers.
//
// Structural diagnosis (avg 11.79, median 7 tokens/example):
//   5 preamble + 1 (<< forced) + ~4 SQL tokens + 1 (>>) ≈ 11 tokens
// Many examples get only 3–4 SQL tokens before IsCompletePrefix fires. Adding a
// minimum SQL-token threshold (minSqlTokens = 8) before allowing IsCompletePrefix
// close forces the model to produce at least a FROM clause before the span is closed.
// At 8+ tokens, simple queries ("SELECT COUNT(*) FROM singer" ≈ 7 tokens) still
// produce a valid IsCompletePrefix just above the threshold, while truncated
// "SELECT city" or "SELECT col" patterns are forced to continue toward correct
// FROM/WHERE/GROUP BY structure.
//
// All other structure from attempt 41 is preserved:
//   - 5-step preamble allows natural "SQL: <<" emission
//   - OpenConstrainedSpan forces "<<" if not already opened
//   - GroupBoostedConstrainedStep(6.0) for schema-token grounding
//   - CloseSpanWithinBudget capped at 80 to prevent repetition loops
//   - Same guidance string (attempt 39 guidance change hurt -9.4pp)
//
// Expected effect: by forcing 8+ SQL tokens, medium/complex queries (which need
// 10–25 tokens) get a full chance to materialize correct table references and
// WHERE/JOIN conditions, reducing the ~132 semantic-mismatch failures.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (preamble): Loop guard requires !insideConstrainedOut; the implication
//   is vacuous throughout. When RenderedEndsWith detects "<<", we set
//   currentConstrainedOut := [] which satisfies IsValidPrefix([]) by method
//   precondition. On EOS break, insideConstrainedOut stays false.
//
// Phase 2 (OpenConstrainedSpan): Only runs when !insideConstrainedOut.
//   OpenConstrainedSpan sets currentConstrainedOut := [], which satisfies
//   IsValidPrefix([]) by precondition. insideConstrainedOut := true.
//
// Phase 3 (constrained generation loop):
//   IsCompletePrefix branch: CloseConstrainedSpan sets insideConstrainedOut := false,
//   making the implication vacuously true, and currentConstrainedOut := [].
//   GroupBoostedConstrainedStep hard-masks to parser-valid tokens plus EOS; on
//   non-EOS, AppendConstrainedToken extends currentConstrainedOut by one parser-valid
//   token, preserving IsValidPrefix by the parser extension contract.
//   EOS path: optional CloseConstrainedSpan sets inside := false; otherwise break
//   with no mutation of parser state.
//
// Phase 4 (cleanup):
//   IsCompletePrefix branch: CloseConstrainedSpan sets inside := false.
//   CloseSpanWithinBudget postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut), so the invariant holds in
//   both the closed and still-open cases.
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1 token.
// Phase 2: OpenConstrainedSpan increments steps by 1, appends exactly 1 "<<" token.
// Phase 3: IsCompletePrefix branch: CloseConstrainedSpan increments steps by 1,
//   appends at most 1 ">>" token. GroupBoostedConstrainedStep branch: steps += 1;
//   AppendConstrainedToken appends 1 token without incrementing steps. Net: per
//   iteration steps grows by 1, generated grows by at most 1. Preserved.
//   EOS path: optional CloseConstrainedSpan: steps += 1, generated grows by at most 1.
// Phase 4 (IsCompletePrefix): steps += 1, generated grows by at most 1. Preserved.
// Phase 4 (CloseSpanWithinBudget): closeBudget = min(remaining, 80) where
//   remaining = maxSteps - steps_before. By CloseSpanWithinBudget postcondition,
//   |generatedOut| <= |generated_before| + closeBudget. We set steps := steps + closeBudget,
//   so |generated_after| <= |generatedPrefix| + steps_before + closeBudget = |generatedPrefix| + steps_after.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Output SQL: <<query>> where the query is a valid SQL SELECT statement using only the given schema tables and columns. Put your answer between << and >>. No explanation.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;

// Phase 1: Short unconstrained preamble (at most 5 steps) to emit "SQL: " prefix
var preambleBudget: nat := 5;
var preambleSteps: nat := 0;

while steps < maxSteps && preambleSteps < preambleBudget && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant 0 <= preambleSteps <= preambleBudget
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  preambleSteps := preambleSteps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard constrained control with group boosting.
// Require at least minSqlTokens SQL tokens before allowing IsCompletePrefix early-close.
// This prevents premature closure on too-short SQL prefixes like "SELECT city"
// and forces the model to generate FROM clauses and WHERE conditions.
var minSqlTokens: nat := 8;
var sqlTokensGenerated: nat := 0;

while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) && sqlTokensGenerated >= minSqlTokens {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
      sqlTokensGenerated := sqlTokensGenerated + 1;
    }
  }
}

// Phase 4: If span still open and budget remains, attempt clean closure.
// Cap CloseSpanWithinBudget at 80 steps to prevent repetition loops from
// consuming the remaining ~800-step budget with garbage output.
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remainingBudget := maxSteps - steps;
    var closeBudget: nat;
    if remainingBudget <= 80 {
      closeBudget := remainingBudget;
    } else {
      closeBudget := 80;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

